sys_script_include.script:
var assetRequestAjaxUtils = Class.create();
assetRequestAjaxUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

	// Get assignment group based on Asset Type

	getAssignmentGroup : function () {
		var assetType = this.getParameter('sysparm_asset_type');

		var groupName = '';

		if (assetType == 'computer') {
			groupName = 'Computers';
		} else if (assetType == 'netgear') {
			groupName = 'Network Gear';
		} else if (assetType == 'printer') {
			groupName = 'Printers';
		} else if (assetType == 'ups') {
			groupName = 'UPS';
		}

		var grGroup = new GlideRecord('sys_user_group');
		grGroup.addQuery('name', groupName);
		grGroup.query();

		if (grGroup.next()) {
			gs.info('IT Asset : ' + grGroup.getUniqueValue());
			return grGroup.getUniqueValue();
		}
	},

	// Get Requestor VIP Status using sys_id

	getUserVIPStatus : function () {
		var user_id = this.getParameter('sysparm_requestor_id');

		var grUser = new GlideRecord('sys_user');

		if (grUser.get('sys_id', user_id)) {
			return grUser.getValue('vip');
		}
	},

	// Get Requestors Company using sys_id

	getRequestorCompany : function () {
		var user_id = this.getParameter('sysparm_requestor_id');

		var grUser = new GlideRecord('sys_user');

		if (grUser.get('sys_id', user_id)) {
			return grUser.getValue('company');
		}
	},

    type: 'assetRequestAjaxUtils'
});
